function art(id,night=false){if(["dove","flower","tree","train","bridge","duck","snail"].includes(id)){const single=["duck","snail"].includes(id);return `<div class="asset-art ${single?"single":"paired"} ${night?"asset-night":""}" role="img" aria-label="${DATA.find(d=>d.id===id)?.description}">${single?`<img src="assets/${id}${night?"-night":"-day"}.png" alt="" loading="lazy">`:`<svg class="paired-crop" viewBox="${night?ASSET_SIZES[id][0]/2+12:12} 0 ${ASSET_SIZES[id][0]/2-24} ${ASSET_SIZES[id][1]}" aria-hidden="true"><defs><clipPath id="crop-${id}-${night}"><rect x="${night?ASSET_SIZES[id][0]/2+12:12}" y="0" width="${ASSET_SIZES[id][0]/2-24}" height="${ASSET_SIZES[id][1]}"/></clipPath></defs><image clip-path="url(#crop-${id}-${night})" href="assets/${id}.png" width="${ASSET_SIZES[id][0]}" height="${ASSET_SIZES[id][1]}"/></svg>`}</div>`;}return `<svg viewBox="0 0 200 180" role="img" aria-label="${DATA.find(d=>d.id===id)?.cn||'神秘发现'}">${iconShapes[id]||iconShapes.mystery}</svg>`}
function duola(state=''){
 const curious=S.voiceStatus==='listening'||S.voiceStatus==='thinking',happy=S.act===4;
 const view=curious?'440 140 210 275':happy?'105 405 220 325':'105 65 220 350';
 return `<div data-mood="${curious?'curious':happy?'happy':'neutral'}" class="duola assistant-portrait ${state} ${S.speaking?'is-speaking':''}" role="img" aria-label="哆啦兔子助手${S.speaking?'正在说话':''}"><svg viewBox="${view}"><image href="assets/assistant-expressions.png" width="1394" height="754"/>${!curious&&!happy?'<g class="assistant-mouth"><ellipse cx="210" cy="292" rx="20" ry="12" fill="#fffdf4"/><path d="M194 289q8 12 16 0q8 12 16 0" fill="none" stroke="#795d50" stroke-width="2.5"/><ellipse class="mouth-open" cx="210" cy="296" rx="7" ry="9" fill="#885c50"/><ellipse class="mouth-tongue" cx="210" cy="301" rx="4" ry="3" fill="#dfa49b"/></g>':''}</svg><span class="assistant-name">哆啦 · 陪你发现</span></div>`;
}
function setSpeaking(active){S.speaking=active;document.querySelectorAll('.assistant-portrait').forEach(el=>el.classList.toggle('is-speaking',active));}
let collectTimer;
function confirmCard(){
 if(S.act!==3||!S.awaitingCard||S.collecting)return;
 saveHistory();stopAudio();S.collecting=true;render();const state=S,item=S.item;
 collectTimer=setTimeout(()=>{if(S!==state||S.act!==3||S.item!==item||!S.collecting)return;S.collecting=false;S.awaitingCard=false;collect();S.act=4;S.turn=0;render();say('这张'+cur().cn+'卡已经收进今天的发现啦。今天一共收集了'+S.got.length+'张卡。');schedule();},850);
}
