function pages(){return [{type:'cover',id:'',zh:'哆啦翻开故事书，寻找今天留下的小发现。',en:'Dora opens a book of discoveries.'},...S.got.map(d=>({type:'real',id:d.id,zh:d.bookZh||'哆啦停下脚步，仔细观察这个还不认识的发现。',en:d.bookEn||'Dora stops to look at a little mystery.'})),{type:'bridge',id:'',zh:'哆啦收好今天的发现，闭上眼睛开始想象。',en:'Dora closes her eyes and begins to imagine.'},...S.got.map(d=>({type:'dream',id:d.id,zh:d.dreamZh||'哆啦想象神秘发现发着光，沿着光点寻找它的轮廓。',en:d.dreamEn||'Dora imagines a little mystery glowing.'})),{type:'end',id:'',zh:'哆啦合上故事书，把新的问题留给明天。',en:'Dora closes the book and saves a question for tomorrow.'}].map(p=>({...p,text:p.zh+' '+p.en}));}
function selectItem(index){if(!Number.isInteger(index)||!DATA[index])return;S.item=index;S.mystery=false;jump(1);}
function goHome(){jump(5);}
